// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address newOwner) public {
        // Only the current owner may invoke transferOwnership; keep the actor in the admissible domain.
        vm.assume(actor == c.owner());
        vm.prank(actor);
        bool ok;
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }
        // General rule: whenever the owner's transfer succeeds, ownership moves to newOwner.
        assertTrue(!ok || c.owner() == newOwner);
    }
}

