pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner1, address caller) public {
        vm.assume(owner1 != address(0));
        vm.assume(caller != address(0));
        // owner1 becomes the rightful owner via the only valid path
        vm.prank(address(0));
        c.transferOwnership(owner1);
        // drive the contract through owned() from the rightful owner
        vm.prank(owner1);
        try c.owned() {
            // rule: a call to owned() by the rightful owner must not change ownership
            assertTrue(c.owner() == owner1);
        } catch {
            // if it reverts, ownership must still be intact
            assertTrue(c.owner() == owner1);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address transferredTo) public {
        vm.assume(actor != address(0));
        vm.assume(transferredTo != address(0));
        // WIDE domain: any non-zero actor, any non-zero new owner.
        // Set up: make actor the owner via transferOwnership (as current owner),
        // then have actor call owned() and check owner is unchanged.
        address currentOwner = c.owner();
        vm.startPrank(currentOwner);
        c.transferOwnership(transferredTo);
        vm.stopPrank();
        currentOwner = c.owner();
        // Drive c through `owned` with the (possibly new) owner calling.
        vm.prank(currentOwner);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        // Rule: owned() must never change the owner, for ANY input.
        assertTrue(c.owner() == (ok ? currentOwner : c.owner()), "owned() must not change owner");
    }
}

