// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address other) public {
        vm.assume(caller != address(0));
        vm.assume(other != address(0));
        vm.assume(caller != other);

        // initial owner is address(0); use it to hand ownership to `caller`
        vm.prank(address(0));
        c.transferOwnership(caller);

        // owner calls owned(); in the correct contract this must be a no-op
        vm.prank(caller);
        c.owned();

        // owner transfers ownership to `other`
        vm.prank(caller);
        c.transferOwnership(other);

        // owner calls owned() again; ownership must remain `other`,
        // since owned() may never change the owner (only transferOwnership can)
        vm.prank(caller);
        c.owned();

        assertTrue(c.owner() == other);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner0, address newOwner, address caller) public {
        // Admissible domain: all three addresses are meaningful, distinct enough to exercise the rule.
        vm.assume(owner0 != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(caller != address(0));
        vm.assume(caller != newOwner);

        // Establish owner0 as owner via transferOwnership (initial owner is address(0), so
        // transferOwnership itself is only callable via prank on address(0)).
        vm.prank(address(0));
        c.transferOwnership(owner0);

        // Current owner transfers ownership to newOwner.
        vm.prank(owner0);
        c.transferOwnership(newOwner);

        // A successful owned() call is only possible from the current owner, and must not
        // change ownership away from the transferred-to owner.
        vm.prank(caller);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }

        if (ok) {
            // General rule: ownership changes only via transferOwnership; owned() must leave
            // owner equal to the value set by the last transferOwnership.
            assertTrue(c.owner() == newOwner, "owned() must not change ownership");
        } else {
            // If the call reverted (caller was not the owner), ownership must still be newOwner.
            assertTrue(c.owner() == newOwner, "failed owned() must not change ownership");
        }
    }
}
